sources = []


def source(id, title, kind, locator, url, summary, *, author="", status="text_checked", use="education", rights="not-assessed", reuse_mode="editorial-paraphrase-only", note=""):
    sources.append(dict(id=id, title=title, category=kind, locator=locator, url=url,
                        author=author, summary=summary, verification=status, use=use,
                        rights=rights, reuse_mode=reuse_mode, reviewed_at="2026-10-27", scholar_reviewed=False, caveat=note))


quran = [
 ("q-yusuf-4", "رؤيا يوسف عليه السلام", "12:4", "ذكر الكواكب والشمس والقمر في رؤيا يوسف؛ مثال قرآني في سياق قصة محددة."),
 ("q-yusuf-5", "حفظ الرؤيا واختيار من تُقص عليه", "12:5", "توجيه يعقوب ليوسف بألا يقص رؤياه على إخوته في تلك الواقعة."),
 ("q-yusuf-6", "تعليم تأويل الأحاديث", "12:6", "ذكر تعليم يوسف من تأويل الأحاديث في سياق اصطفائه."),
 ("q-yusuf-36", "رؤيا صاحبي السجن", "12:36", "وردت رؤيتان مختلفتان فيهما العصر والخبز والطير؛ لا تُفصل الرموز عن القصة."),
 ("q-yusuf-41", "تأويل رؤيتي صاحبي السجن", "12:41", "تأويل يوسف في واقعة بعينها؛ لا يجيز تنبؤ المنصة بموت شخص أو عقوبته."),
 ("q-yusuf-43", "رؤيا الملك: البقر والسنابل", "12:43", "عرض الرؤيا بتفاصيل عدد البقر وصفته والسنابل وحالها."),
 ("q-yusuf-44", "أضغاث أحلام وحدود المعرفة", "12:44", "جواب الملأ عن رؤيا الملك، وهم لم يعرفوا تأويلها؛ وصفهم ليس حكماً بصحة جوابهم."),
 ("q-yusuf-47", "التأويل والتدبير في قصة يوسف", "12:47", "تأويل خاص بسبع سنوات من الزرع مع تدبير حفظ المحصول."),
 ("q-yusuf-48", "سنوات الشدة في القصة", "12:48", "استكمال تأويل يوسف لرؤيا الملك في سياق محدد، لا جدول لتوقيت أحلام الناس."),
 ("q-yusuf-49", "عام الغيث في القصة", "12:49", "خبر يوسف في ختام التأويل؛ لا يُعمم على أي حلم بالمطر."),
 ("q-yusuf-100", "تحقق رؤيا يوسف", "12:100", "ربط الرؤيا السابقة بتحققها في نهاية القصة؛ لا معيار آلياً لتصديق منام جديد."),
 ("q-saffat-102", "رؤيا إبراهيم عليه السلام", "37:102", "رؤيا نبي؛ لا تُسوّى بها أوامر أحلام غير الأنبياء ولا تُتخذ ذريعة لإيذاء أحد."),
 ("q-fath-27", "صدق رؤيا الرسول ﷺ", "48:27", "نص في رؤيا الرسول ودخول المسجد الحرام؛ لا وعد تلقائياً بالحج لكل راءٍ."),
 ("q-naml-65", "الغيب لله", "27:65", "أصل عام في اختصاص الله بعلم الغيب؛ ليس قاموساً لرموز المنام."),
 ("q-isra-36", "عدم القول بغير علم", "17:36", "أصل عام لضبط نسبة الأقوال وعدم إيهام السائل بأن التخمين علم."),
 ("q-hujurat-12", "اجتناب كثير من الظن", "49:12", "أصل عام يحول دون تحويل المنام إلى اتهام للناس أو تجسس عليهم."),
 ("q-najm-28", "حدود الظن", "53:28", "أصل عام للتفريق بين اليقين والظن، وليس إثباتاً لمعنى رمز بعينه."),
]
for id, title, verse, summary in quran:
    sura, aya = verse.split(":")
    source(id, title, "quran", verse, f"https://quran.com/{sura}/{aya}", summary,
           author="القرآن الكريم", use="core", rights="public-domain",
           note="ثبوت النص لا يثبت انطباق تأويل رؤيا بعينها على حلم المستخدم.")

hadith = [
 ("h-muslim-2263", "أقسام الرؤيا وحديث النفس", "مسلم 2263 أ", "muslim:2263a", "تقسيم الرؤى إلى بشرى وتحزين وحديث نفس، والتوجيه للصلاة وترك التحديث بالمكروه."),
 ("h-bukhari-6985", "حمد الله على الرؤيا المحبوبة", "البخاري 6985", "bukhari:6985", "حمد الله عند رؤية المحبوب، والاستعاذة وعدم نشر المكروه."),
 ("h-bukhari-6990", "الرؤيا الصالحة من المبشرات", "البخاري 6990", "bukhari:6990", "بيان المبشرات؛ لا يمنح تعبير المنصة عصمة أو صفة الوحي."),
 ("h-bukhari-6994", "رؤية النبي ﷺ في المنام", "البخاري 6994", "bukhari:6994", "النص في رؤية النبي؛ التثبت في تنزيله على وصف شخص في منام يحتاج عالماً، ولا تحسمه المنصة."),
 ("h-bukhari-7006", "تأويل اللبن بالعلم في رؤيا نبوية", "البخاري 7006", "bukhari:7006", "ورد تأويل اللبن بالعلم في رؤيا محددة للنبي ﷺ تتعلق بعمر رضي الله عنه."),
 ("h-bukhari-7008", "تأويل القميص بالدين في رؤيا نبوية", "البخاري 7008", "bukhari:7008", "ورد تأويل القميص بالدين في رؤيا محددة؛ لا يُقاس تدين الأشخاص من طول لباسهم في أحلام الناس."),
 ("h-bukhari-7043", "التحذير من اختلاق الرؤيا", "البخاري 7043", "bukhari:7043", "النهي عن دعوى رؤية ما لم يره الإنسان؛ أمثلة المنصة التعليمية موسومة بأنها أمثلة."),
 ("h-bukhari-7046", "المعبّر يصيب ويخطئ", "البخاري 7046", "bukhari:7046", "بيّن النبي ﷺ لأبي بكر أنه أصاب بعض التعبير وأخطأ بعضه؛ فالتعبير يحتمل الخطأ."),
 ("h-muslim-2261", "النفث والاستعاذة عند المكروه", "مسلم 2261 أ", "muslim:2261a", "التوجيه بالاستعاذة والنفث عند رؤية ما يكره النائم."),
 ("h-muslim-2262", "التحول عن الجنب عند الحلم المكروه", "مسلم 2262", "muslim:2262", "الاستعاذة والنفث عن اليسار ثلاثاً والتحول عن الجنب الذي كان عليه."),
 ("h-muslim-2268", "عدم التحديث بتلاعب الشيطان", "مسلم 2268 د", "muslim:2268d", "في خبر المنام المزعج توجيه بترك التحديث به، دون تكلف البحث عن نذير مستقبلي."),
 ("h-muslim-2270", "الاستئناس بدلالة الأسماء في واقعة", "مسلم 2270", "muslim:2270", "تأويل الرفعة والعاقبة وطيب الدين في رؤيا نبوية وردت فيها أسماء عقبة ورافع وابن طاب."),
]
for id, title, locator, urlpart, summary in hadith:
    source(id, title, "hadith", locator, f"https://sunnah.com/{urlpart}", summary,
           author="مسلم بن الحجاج" if "muslim" in id else "محمد بن إسماعيل البخاري",
           use="core", note="المتن الأصلي في الصحيح. التطبيق على حلم جديد اجتهاد مستقل، ولا نعيد نشر الترجمة الحديثة.")

